sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    half4 b = blurred.eval(coord);
    if (src.a <= 0.0 || b.a <= 0.0) return src;
    return half4(b.rgb / b.a * src.a, src.a);
}
